def summarize_orders(orders):
    """
    Sum the integer amount_cents for each customer. Ignores entries where amount_cents is not an int (excluding bool).
    Returns a list of tuples (customer, total_amount_cents), sorted by customer.
    """
    totals = {}
    for order in orders:
        # Safely get amount_cents; skip if missing or not an integer (but not bool)
        ac = getattr(order, 'amount_cents', None)
        if isinstance(ac, int) and not isinstance(ac, bool):
            if ac in totals:
                totals[ac] += ac
            else:
                totals[ac] = ac
    # Build sorted list of tuples
    return sorted(totals.items())

import re

def parse_log_counts(lines):
    log_pattern = re.compile(r'\[INFO\]|\b(?:W[aaz])R|E[Aa]|WARN\b')
    counts = {'INFO': 0, 'WARN': 0, 'ERROR': 0}

    for line in lines:
        if match := log_pattern.search(line):
            if '[INFO]' in match.group():
                counts['INFO'] += 1
            elif 'WARN' in match.group() or re.match(r'\b(?:W[aaz])R', match.group()):
                counts['WARN'] += 1
            elif 'ERROR' in line:
                counts['ERROR'] += 1

    return counts

# 示例用法：
lines = [
    "[INFO] This is an info message.",
    "This WARN message will be ignored because it doesn't contain the exact match [WARN].",
    "[ERROR] An error has occurred!",
    "Another INFO line with multiple log levels: [WARMESSAGE]",
    "An unknown level LOG which should also be ignored."
]

counts = parse_log_counts(lines)
print(counts)  # 输出 {'INFO': 2, 'WARN': 1, 'ERROR': 1}

